#include <stdio.h>
#include <string.h>

#define V 5
#define INF 0x3f3f3f3f

int g[V][V];
int dist[V];
int done[V];

int main(void) {
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++)
            g[i][j] = (i == j) ? 0 : INF;

    int edges[][3] = {{0,1,4},{0,2,1},{2,1,2},{1,3,5},{2,3,8},{2,4,10},{3,4,2}};
    int m = (int)(sizeof(edges) / sizeof(edges[0]));
    for (int i = 0; i < m; i++) {
        int u = edges[i][0], v = edges[i][1], w = edges[i][2];
        g[u][v] = g[v][u] = w;   /* 无向图 */
    }

    for (int i = 0; i < V; i++) dist[i] = INF;
    dist[0] = 0;

    printf("Dijkstra 朴素版，源点 0：\n");
    for (int round = 0; round < V; round++) {
        int u = -1, best = INF;
        for (int i = 0; i < V; i++)
            if (!done[i] && dist[i] < best) { best = dist[i]; u = i; }
        if (u == -1) break;
        done[u] = 1;
        printf("  第 %d 轮确定 %d（dist=%d）\n", round + 1, u, dist[u]);

        for (int v = 0; v < V; v++) {
            if (done[v] || g[u][v] == INF) continue;
            if (dist[u] + g[u][v] < dist[v]) {
                if (dist[v] >= INF)
                    printf("    松弛 %d -> %d：INF -> %d\n", u, v, dist[u] + g[u][v]);
                else
                    printf("    松弛 %d -> %d：%d -> %d\n", u, v, dist[v], dist[u] + g[u][v]);
                dist[v] = dist[u] + g[u][v];
            }
        }
    }

    printf("\n最终 dist：");
    for (int i = 0; i < V; i++) printf("0->%d = %d   ", i, dist[i]);
    printf("\n");

    printf("\n要点：正确性依赖「非负权」。若有权为负，「当前最小者已最终确定」这一断言失效，\n");
    printf("      必须改用 Bellman-Ford。朴素版无堆操作、纯数组循环，在稠密图上常快于堆优化版。\n");
    return 0;
}
